  await page.locator('summary').click();
  await page.getByLabel(ReproductionControl.board, { exact: true }).fill(EXAMPLE_CODE);
  await page.getByRole('button', { name: ReproductionControl.loadBoard, exact: true }).click();
  await page.locator('summary').click();
  await expect(page.locator('.card')).toHaveCount(16);
}

export async function loadTimedBoard(page: Page, url = GAME_URL): Promise<void> {
  await page.clock.install({ time: CLOCK_START });
  await loadFixedBoard(page, url);
  await page.clock.pauseAt(CLOCK_PAUSE);
}

export async function exportedSnapshot(page: Page): Promise<Record<string, unknown>> {
  await page.locator('summary').click();
  await page.getByRole('button', { name: ReproductionControl.exportSnapshot, exact: true }).click();
  const value: unknown = JSON.parse(
    await page.getByLabel(ReproductionControl.snapshot, { exact: true }).inputValue(),
  );
  await page.locator('summary').click();
  if (!isJsonObject(value)) throw new Error('Expected an exported snapshot object.');
  return value;
}

export async function moves(page: Page): Promise<number> {
  return Number(
    await page
      .locator('.stats > div')
      .filter({ has: page.getByText(StatusLabel.moves, { exact: true }) })
      .locator('dd')
      .textContent(),
  );
}

export async function finishBoard(page: Page): Promise<void> {
  for (const pair of EXAMPLE_PAIRS)
    for (const index of pair) await page.locator('.card').nth(index).click();
  await expect(page.locator('.card.matched')).toHaveCount(EXAMPLE_PAIRS.length * 2);
}

export const SNAPSHOT_PATH = fileURLToPath(new URL('./ui.fixture.json', import.meta.url));
import { useRef, useState } from 'react';
import { createGame } from '../game.ts';
import { parseBoardCode, isValidSize } from '../deck.ts';
import { decodeSnapshotData, encodeSnapshot, isValidDealName } from '../snapshot.ts';
import { freshBoardCode } from './fresh-board.ts';
import { activateSession, initialSession, replaceGame, SessionNotice } from './session.ts';
import { readPreferences } from './storage.ts';
import { browserStore, useSavedPreferences } from './use-saved-preferences.ts';
import { useSessionClock } from './use-session-clock.ts';
import type { Session } from './session.ts';

export function useGame() {
  const [store] = useState(browserStore);
  const [session, setSession] = useState(() => {
    const preferences = readPreferences(store);
    return initialSession(freshBoardCode(preferences.size), preferences);
  });
  const current = useRef(session);

  function commit(next: Session): void {
    if (next === current.current) return;
    current.current = next;
    setSession(next);
  }

  const clock = useSessionClock(session, current, commit);
  useSavedPreferences(store, session.preferences);

  function newGame(size = current.current.game.size): void {
    if (!isValidSize(size)) return;
    const next = createGame(freshBoardCode(size, current.current.game.seed));
    clock.reset();
    commit(replaceGame(current.current, next, false));
  }

  function restart(): void {
    clock.reset();
    commit(replaceGame(current.current, createGame(current.current.game.boardCode), false));
  }

  function notice(feedback: string): void {
    commit({
      ...current.current,
      feedback,
      loadNotice: feedback,
      announcement: current.current.announcement + 1,
    });
  }

  function loadBoard(code: string): boolean {
    code = code.trim();
    if (!parseBoardCode(code)) {
      notice(SessionNotice.invalidBoard);
      return false;
    }
    clock.reset();
    commit(replaceGame(current.current, createGame(code), false));
    return true;
  }

  function loadSnapshot(text: string): boolean {
    const snapshot = decodeSnapshotData(text);
    if (!snapshot) {
      notice(SessionNotice.invalidSnapshot);
      return false;
    }
    clock.reset();
    commit(replaceGame(current.current, snapshot.game, true, snapshot.name));
    return true;
  }

  function setName(name: string): void {
    if (!isValidDealName(name) || name === current.current.name) return;
    commit({ ...current.current, name });
  }

  function exportSnapshot(): string {
    // Rendered state can trail the active clock by a tick.
    clock.synchronize();
    return encodeSnapshot(current.current.game, current.current.name);
  }

  function activate(index: number): void {
    clock.synchronize();
    commit(activateSession(current.current, index));
  }

  function resume(): void {
    clock.reset();
    commit({
      ...current.current,
      paused: false,
      feedback: '',
      loadNotice: '',
    });
  }

  return {
    session,
    newGame,
    restart,
    loadBoard,
    loadSnapshot,
    setName,
    exportSnapshot,
    activate,
    resume,
  };
}
import { createGame, MOVES_MAX, ELAPSED_MAX_MS } from './game.ts';
import { parseBoardCode } from './deck.ts';
import {
  hasExactKeys,
  isJsonObject,
  isNonnegativeSafeInteger,
  isWithinBytes,
  parseJson,
} from './saved-format.ts';
import { readMatched, readSelection } from './snapshot-selection.ts';
import { SelectionKind } from './selection.ts';
import type { GameState } from './game.ts';

export const SNAPSHOT_VERSION = 1;
export const NAMED_SNAPSHOT_VERSION = 2;
export const SNAPSHOT_MAX_BYTES = 65_536;
export const SNAPSHOT_NAME_MAX_CHARACTERS = 40;
export const SNAPSHOT_KEYS = [
  'version',
  'boardCode',
  'matched',
  'selection',
  'moves',
  'elapsedMs',
  'started',
] as const;
export const NAMED_SNAPSHOT_KEYS = ['version', 'name', ...SNAPSHOT_KEYS.slice(1)] as const;

export interface DecodedSnapshot {
  readonly game: GameState;
  readonly name: string;
}

export function isValidDealName(value: unknown): value is string {
  return (
    typeof value === 'string' &&
    value.length <= SNAPSHOT_NAME_MAX_CHARACTERS &&
    !value.includes('\r') &&
    !value.includes('\n')
  );
}

export function encodeSnapshot(state: GameState, name = ''): string {
  const fields = {
    boardCode: state.boardCode,
    matched: [...state.matched].sort((left, right) => left - right),
    // Active time keeps its fractions in play. Export writes whole milliseconds, and rounding
    // pending time up keeps a mismatch at 1ms or more.
    selection:
      state.selection.kind === SelectionKind.mismatch
        ? { ...state.selection, remainingMs: Math.ceil(state.selection.remainingMs) }
        : state.selection,
    moves: state.moves,
    elapsedMs: Math.floor(state.elapsedMs),
    started: state.started,
  };
  const value = name.length > 0 && isValidDealName(name)
    ? { version: NAMED_SNAPSHOT_VERSION, name, ...fields }
    : { version: SNAPSHOT_VERSION, ...fields };
  return JSON.stringify(value, null, 2);
}

export function decodeSnapshotData(text: string): DecodedSnapshot | null {
  const value = isWithinBytes(text, SNAPSHOT_MAX_BYTES) ? parseJson(text) : undefined;
  if (!isJsonObject(value)) return null;
  const named = value.version === NAMED_SNAPSHOT_VERSION;
  if (value.version !== SNAPSHOT_VERSION && !named) return null;
  const keys = named ? NAMED_SNAPSHOT_KEYS : SNAPSHOT_KEYS;
  if (!hasExactKeys(value, keys)) return null;
  let name = '';
  if (named) {
    if (!isValidDealName(value.name) || value.name.length === 0) return null;
    name = value.name;
  }
  if (typeof value.boardCode !== 'string' || !parseBoardCode(value.boardCode)) return null;
  if (
    !isNonnegativeSafeInteger(value.moves) ||
    value.moves > MOVES_MAX ||
    !isNonnegativeSafeInteger(value.elapsedMs) ||
    value.elapsedMs > ELAPSED_MAX_MS ||
    typeof value.started !== 'boolean'
  )
    return null;
  const initial = createGame(value.boardCode);
  const matched = readMatched(value.matched, initial);
  if (!matched) return null;
  const selection = readSelection(value.selection, initial, matched);
  if (!selection) return null;
  const state: GameState = {
    ...initial,
    matched,
    selection,
    moves: value.moves,
    elapsedMs: value.elapsedMs,
    started: value.started,
  };
  const minimumMoves = matched.length / 2 + (selection.kind === SelectionKind.mismatch ? 1 : 0);
  if (state.moves < minimumMoves) return null;
  if (
    !state.started &&
    (state.moves !== 0 ||
      state.elapsedMs !== 0 ||
      matched.length !== 0 ||
      selection.kind !== SelectionKind.closed)
  )
    return null;
  if (state.started && state.moves === 0 && selection.kind === SelectionKind.closed) return null;
  return { game: state, name };
}

export function decodeSnapshot(text: string): GameState | null {
  return decodeSnapshotData(text)?.game ?? null;
}
import assert from 'node:assert/strict';
import { test } from 'vitest';
import { activateCard, advanceGame, createGame, MISMATCH_MS, MOVES_MAX } from './game.ts';
import {
  decodeSnapshot,
  decodeSnapshotData,
  encodeSnapshot,
  isValidDealName,
  NAMED_SNAPSHOT_KEYS,
  NAMED_SNAPSHOT_VERSION,
  SNAPSHOT_KEYS,
  SNAPSHOT_MAX_BYTES,
  SNAPSHOT_VERSION,
} from './snapshot.ts';
import { SelectionKind } from './selection.ts';
import { isJsonObject } from './saved-format.ts';
import { EXAMPLE_CODE, EXAMPLE_PAIRS, SPEC_VECTOR } from './game.fixture.ts';

function snapshot(overrides: Record<string, unknown> = {}): string {
  return JSON.stringify({
    version: SNAPSHOT_VERSION,
    boardCode: EXAMPLE_CODE,
    matched: [],
    selection: { kind: SelectionKind.closed },
    moves: 0,
    elapsedMs: 0,
    started: false,
    ...overrides,
  });
}

test('snapshot round trips preserve pending time and serialize only the declared fields', () => {
  const state = advanceGame(activateCard(activateCard(createGame(EXAMPLE_CODE), 0), 1), 175);
  assert.deepEqual(decodeSnapshot(encodeSnapshot(state)), state);
  assert.deepEqual(state.selection, {
    kind: SelectionKind.mismatch,
    first: 0,
    second: 1,
    remainingMs: MISMATCH_MS - 175,
  });
  assert.equal(SNAPSHOT_VERSION, SPEC_VECTOR.snapshotVersion);
  assert.equal(SNAPSHOT_MAX_BYTES, SPEC_VECTOR.snapshotBytes);
  const exported: unknown = JSON.parse(encodeSnapshot(state));
  assert.ok(exported && typeof exported === 'object');
  assert.deepEqual(Object.keys(exported).sort(), [...SNAPSHOT_KEYS].sort());
});

test('snapshot imports accept property order changes while keeping the exact key set', () => {
  const reordered = JSON.stringify({
    boardCode: EXAMPLE_CODE,
    matched: [],
    selection: { kind: SelectionKind.closed },
    moves: 0,
    elapsedMs: 0,
    started: false,
    version: SNAPSHOT_VERSION,
  });
  assert.ok(decodeSnapshot(reordered));
  const withExtra = JSON.stringify({
    version: SNAPSHOT_VERSION,
    boardCode: EXAMPLE_CODE,
    matched: [],
    selection: { kind: SelectionKind.closed },
    moves: 0,
    elapsedMs: 0,
    started: false,
    extra: true,
  });
  assert.equal(decodeSnapshot(withExtra), null);
});

test('named snapshots round trip their name and version 1 imports have no name', () => {
  const state = activateCard(createGame(EXAMPLE_CODE), 0);
  const name = '  Café 🃏  ';
  const text = encodeSnapshot(state, name);
  const exported: unknown = JSON.parse(text);
  if (!isJsonObject(exported)) throw new Error('Expected a snapshot object.');
  assert.deepEqual(Object.keys(exported).sort(), [...NAMED_SNAPSHOT_KEYS].sort());
  assert.equal(exported.version, NAMED_SNAPSHOT_VERSION);
  assert.equal(exported.name, name);
  assert.deepEqual(decodeSnapshotData(text), { game: state, name });
  assert.equal(decodeSnapshotData(snapshot())?.name, '');
});

test('deal names follow the 40 UTF-16 code unit and line break rules', () => {
  assert.equal(isValidDealName(''), true);
  assert.equal(isValidDealName('  kept  '), true);
  assert.equal(isValidDealName('🃏'.repeat(20)), true);
  assert.equal(isValidDealName('🃏'.repeat(21)), false);
  for (const name of ['', 'x'.repeat(41), 'bad\rname', 'bad\nname']) {
    assert.equal(decodeSnapshotData(snapshot({ version: 2, name })), null);
  }
});

test('snapshots accept whole pairs and completed states without changing the source order', () => {
  const state = activateCard(activateCard(createGame(EXAMPLE_CODE), 6), 2);
  assert.deepEqual(decodeSnapshot(encodeSnapshot(state))?.matched, [2, 6]);
  assert.deepEqual(state.matched, [6, 2]);
  assert.equal(
    decodeSnapshot(
      snapshot({ matched: EXAMPLE_PAIRS.flat(), moves: EXAMPLE_PAIRS.length, started: true }),
    )?.matched.length,
    16,
  );
  assert.ok(decodeSnapshot(snapshot({ moves: 17, started: true })));
});

const INVALID_SNAPSHOTS: readonly Record<string, unknown>[] = [
