    18	}
    19	
    20	export const SessionNotice = {
    21	  loaded: 'Loaded snapshot. Select Resume to continue.',
    22	  loadedCompleted: 'Loaded completed snapshot.',
    23	  invalidBoard: 'Invalid board code.',
    24	  invalidSnapshot: 'Invalid snapshot.',
    25	} as const;
    26	
    27	export function initialSession(code: string, preferences: Preferences): Session {
    28	  return {
    29	    game: createGame(code),
    30	    name: '',
    31	    paused: false,
    32	    generation: 0,
    33	    feedback: '',
    34	    loadNotice: '',
    35	    announcement: 0,
    36	    celebration: false,
    37	    preferences,
    38	  };
    39	}
    40	
    41	export function replaceGame(
    42	  session: Session,
    43	  game: GameState,
    44	  imported: boolean,
    45	  name = '',
    46	): Session {
    47	  const paused = imported && !isWon(game);
    48	  const loadNotice = imported
    49	    ? paused
    50	      ? SessionNotice.loaded
    51	      : SessionNotice.loadedCompleted
    52	    : '';
    53	  return {
    54	    ...session,
    55	    game,
    56	    name: imported ? name : '',
    57	    paused,
    58	    generation: session.generation + 1,
    59	    celebration: false,
    60	    preferences: { ...session.preferences, size: game.size },
    61	    // Only loads have a published status. A new deal clears the last turn result silently.
    62	    announcement: imported ? session.announcement + 1 : session.announcement,
    63	    feedback: loadNotice,
    64	    loadNotice,
    65	  };
    66	}
    67	
    68	export function tickSession(session: Session, generation: number, milliseconds: number): Session {
    69	  if (session.generation !== generation || session.paused) return session;
    70	  const game = advanceGame(session.game, milliseconds);
    71	  return game === session.game ? session : { ...session, game };
